import React from 'react';
import styled from 'styled-components';

const AboutMeContainer = styled.div`
  padding: 20px;
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
`;

const Title = styled.h1`
  font-size: 36px;
  margin-bottom: 20px;
`;

const Specialty = styled.h2`
  font-size: 24px;
  margin-bottom: 20px;
`;

const Description = styled.p`
  font-size: 18px;
  line-height: 1.6;
  text-align: left;
`;

const AboutMe = () => {
  return (
    <AboutMeContainer>
      <Title>ABOUT ME</Title>
      <Specialty>My Specialty</Specialty>
      <Description>
        An experienced Assistant Chef with over 8 years in Bakery and Culinary Arts.
        <br /><br />
        A highly skilled and passionate Assistant Chef with over 8 years of hands-on experience in bakery operations, artisanal baking, and diverse culinary techniques. Adept at crafting high-quality baked goods, including bread, pastries, cakes, and specialty desserts, while ensuring consistency in taste, texture, and presentation. Proficient in ingredient preparation, dough fermentation, and advanced baking methods to create exceptional products that meet both customer preferences and industry standards. Beyond bakery expertise, I bring a strong proficiency in cooking authentic Italian cuisine, mastering classic pasta dishes, risottos, wood-fired pizzas, and traditional sauces with a deep understanding of flavors and techniques. Additionally, I excel in preparing Indian cuisine, specializing in rich curries, tandoori preparations, aromatic biryanis, and a variety of traditional spices and cooking methods.I thrive in fast-paced kitchen environments, collaborating seamlessly with head chefs and culinary teams to maintain smooth kitchen operations. Well-versed in food safety regulations, hygiene protocols, and inventory management, ensuring a well-organized and compliant kitchen. Passionate about creating memorable dining experiences through precision, creativity, and attention to detail.Eager to contribute my expertise to a dynamic culinary team, continually learning and innovating to elevate the quality of food and customer satisfaction.
<br> </br>
Kindly have a look at my Gallery to see some of recent works.
      </Description>
    </AboutMeContainer>
  );
};

export default AboutMe;
